    assure_path_exists(save_path)
    path_file = os.path.join(save_path, filename)
    dbcon = InfluxDBClient(
        INFLUXDB_HOST,
        INFLUXDB_PORT,
        INFLUXDB_USER,
        INFLUXDB_PASSWORD,
        INFLUXDB_DATABASE)
    input_dev = Input.query.filter(Input.unique_id == unique_id).first()
    pixels = []
