    def _package_exists(cls, package):
        cmd = compose_cmd(
            ['dpkg', '--get-selections', '|', 'grep', '-v', 'deinstall', '|', 'cut', '-f1']
        )
        installed_packages = cls.run_shell_command(cmd)
        is_installed = True if package in installed_packages.split('\n') else False
        return is_installed
