def create_app(to_migrate_db=False):
    """Create the Flask app and return it.
    Args:
        to_migrate_db: If True, then only initialize the db.
    Returns:
        Flask.app
    """
    signal.signal(signal.SIGTERM, lambda *args, **kwargs: sys.exit(0))
    app = Flask(__name__)
    app.config.from_object(config.CONFIG_CLASS)
    init_logging()
    if os.getenv("FLASK_ENV") == "development":
        app = register_teardown_request(app)
    socketio = SocketIO(app, cors_allowed_origins="*")
    try:
        global_orchest_config = _utils.GlobalOrchestConfig()
    except _errors.CorruptedFileError:
        app.logger.error("Failed to load global orchest config file.", exc_info=True)
    else:
        app.config.update(global_orchest_config.as_dict())
        global_orchest_config.save(app)
    app.config["ORCHEST_REPO_TAG"] = get_repo_tag()
    if not database_exists(app.config["SQLALCHEMY_DATABASE_URI"]):
        create_database(app.config["SQLALCHEMY_DATABASE_URI"])
    db.init_app(app)
    ma.init_app(app)
    Migrate().init_app(app, db)
    if to_migrate_db:
        return app, None, None
    app.logger.info("Flask CONFIG: %s" % app.config)
    if not app.config["TELEMETRY_DISABLED"]:
        posthog.api_key = base64.b64decode(app.config["POSTHOG_API_KEY"]).decode()
        posthog.host = app.config["POSTHOG_HOST"]
    if not _utils.is_running_from_reloader():
        with app.app_context():
            try:
                if app.config.get("TESTING", False):
                    pass
                else:
                    app.logger.debug("Trying to create /tmp/webserver_init_lock")
                    os.mkdir("/tmp/webserver_init_lock")
                    app.logger.info("/tmp/webserver_init_lock successfully created.")
            except FileExistsError:
                app.logger.info("/tmp/webserver_init_lock already exists.")
            else:
                jupyter_boot_lock_path = os.path.join(
                    "/userdir", _config.JUPYTER_USER_CONFIG, "lab", ".bootlock"
                )
                if os.path.exists(jupyter_boot_lock_path):
                    app.logger.info("Removing dangling jupyter boot lock.")
                    os.rmdir(jupyter_boot_lock_path)
                projs = Project.query.all()
                for proj in projs:
                    try:
                        populate_kernels(app, db, proj.uuid)
                    except Exception as e:
                        logging.error(
                            "Failed to populate kernels on startup"
                            " for project %s: %s [%s]" % (proj.uuid, e, type(e))
                        )
    scheduler = BackgroundScheduler(
        job_defaults={
            "misfire_grace_time": 2 ** 31,
            "coalesce": False,
            "max_instances": 2 ** 31,
        }
    )
    app.config["SCHEDULER"] = scheduler
    add_recurring_jobs_to_scheduler(scheduler, app, run_on_add=True)
    scheduler.start()
    @app.route("/", defaults={"path": ""}, methods=["GET"])
    @app.route("/<path:path>", methods=["GET"])
    def index(path):
        file_path = safe_join(app.config["STATIC_DIR"], path)
        if os.path.isfile(file_path):
            return send_from_directory(app.config["STATIC_DIR"], path)
        else:
            return send_from_directory(
                app.config["STATIC_DIR"], "index.html", cache_timeout=0
            )
    register_views(app, db)
    register_orchest_api_views(app, db)
    register_background_tasks_view(app, db)
    register_socketio_broadcast(socketio)
    register_analytics_views(app, db)
    processes = []
    if (
        os.environ.get("FLASK_ENV") != "development"
        or _utils.is_running_from_reloader()
    ):
        file_dir = os.path.dirname(os.path.realpath(__file__))
        log_streamer_process = Popen(
            ["python3", "-m", "scripts.log_streamer"],
            cwd=os.path.join(file_dir, ".."),
            stderr=subprocess.STDOUT,
        )
        app.logger.info("Started log_streamer.py")
        processes.append(log_streamer_process)
    return app, socketio, processes

def register_views(app, db):
    errors = {}
    api = Api(app, errors=errors)
    projects_schema = ProjectSchema(many=True)
    environment_schema = EnvironmentSchema()
    environments_schema = EnvironmentSchema(many=True)
    background_task_schema = BackgroundTaskSchema()
    def register_environments(db, api):
        class EnvironmentsResource(Resource):
            def get(self, project_uuid):
                if project_exists(project_uuid):
                    return {"message": "Project could not be found."}, 404
                return environments_schema.dump(
                    get_environments(
                        project_uuid, language=request.args.get("language")
                    )
                )
        class EnvironmentResource(Resource):
            def put(self, project_uuid, environment_uuid):
                return self.post(project_uuid, environment_uuid)
            def get(self, project_uuid, environment_uuid):
                environment = get_environment(environment_uuid, project_uuid)
                if environment is None:
                    return {"message": "Environment could not be found."}, 404
                else:
                    return environment_schema.dump(environment)
            def delete(self, project_uuid, environment_uuid):
                delete_environment(app, project_uuid, environment_uuid)
                populate_kernels(app, db, project_uuid)
                return jsonify({"message": "Environment deletion was successful."})
            def post(self, project_uuid, environment_uuid):
                environment_json = request.json.get("environment")
                e = Environment(
                    uuid=str(uuid.uuid4()),
                    name=environment_json["name"],
                    project_uuid=project_uuid,
                    language=environment_json["language"],
                    setup_script=preprocess_script(environment_json["setup_script"]),
                    base_image=environment_json["base_image"],
                    gpu_support=environment_json["gpu_support"],
                )
                if environment_uuid != "new":
                    e.uuid = environment_uuid
                else:
                    url = (
                        f'http://{app.config["ORCHEST_API_ADDRESS"]}'
                        f"/api/environments/{project_uuid}"
                    )
                    resp = requests.post(url, json={"uuid": e.uuid})
                    if resp.status_code != 201:
                        return {}, resp.status_code, resp.headers.items()
                environment_dir = get_environment_directory(e.uuid, project_uuid)
                os.makedirs(environment_dir, exist_ok=True)
                serialize_environment_to_disk(e, environment_dir)
                populate_kernels(app, db, project_uuid)
                return environment_schema.dump(e)
        api.add_resource(
            EnvironmentsResource, "/store/environments/<string:project_uuid>"
        )
        api.add_resource(
            EnvironmentResource,
            "/store/environments/<string:project_uuid>/<string:environment_uuid>",
        )
    register_environments(db, api)
    def return_404(reason=""):
