        pipeline_uuid = request.args.get("pipeline_uuid")
        if path.startswith("/") and not path.startswith("/data"):
            return jsonify({"message": "Illegal file path prefix."}), 400
        file_path = None
        if path.startswith("/"):
            file_path = resolve_absolute_path(path)
